<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
            <span class="p-name text-white">{{ $t(NewTabName) }}</span>
            <span class="p-actions float-right">
                <a  title="Bulk Action" href="javascript:;" class="p-action-btn text-white " @click="BulkAction">
                    <em class="fa fa-plus pr-2"></em> <br>
                    <span>{{ $t('Bulk Action') }}</span>
                </a>
                <a v-if="CheckDisabled()" title="Add Tasks" @click="AddNewTask" href="javascript:;"
                    class="p-action-btn text-white">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t('Add') }} {{ $t(NewTabName) }}</span></a>

                <a  title="Export To Excel" href="javascript:;" @click="ExporttoExcel" class="p-action-btn text-white">
                    <em class="fa fa-upload pr-2"></em> <br><span>{{ $t('Export To Excel') }}</span></a>
                <a  v-if="CheckDisabled()" title="Import To Task" href="javascript:;" @click="EportTask" class="p-action-btn text-white">
                    <em class="fa fa-file-excel-o pr-2"></em> <br><span>{{ $t('Import To Task') }}</span></a>
                <a title="BacktoList" @click="BackToList" class="p-action-btn text-white float-right"
                    data-toggle-tooltip="tooltip" data-original-title="Back to list"><i aria-hidden="true"
                        class="fa fa-angle-double-left"></i><br>{{ $t('BacktoList') }}</a>
            </span>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3">
            <div class="row p-0 pt-2 colcontrol">
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <input class="form-control" :placeholder="dynamicPlaceholderr"
                            @keyup.enter="FetchTaskList(IsTaskName, 'TASK_BY_NAME')" v-model="IsTaskName">
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="TypeFilter" :options="ProjectBacklogType" placeholder="Task Type"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchTaskList(TypeFilter, 'TASK_BY_TYPE')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="QuickFilter" :options="QuickfilterBacklogType" placeholder="Task Assignee"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchTaskList(QuickFilter, 'TASK_BY_ASSIGN_USER')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="PriorityFilter" :options="FilterPriorityData" placeholder="Priority"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchTaskList(PriorityFilter, 'TASK_BY_PRIORITY')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="StatusFilter" :options="StatusData" placeholder="Status" :multiple="true"
                            :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchTaskList(StatusFilter, 'TASK_BY_STATUS')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="form-group mb-2">
                        <Treeselect v-model="SprintFilter" :options="SprintData" placeholder="Sprint" :multiple="true"
                            :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchTaskList(SprintFilter, 'TASK_BY_SPRINT')"></Treeselect>
                    </div>
                </div>
                <div class="col float-left">
                    <div class="background-0 text-left form-check-inline">
                        <a href="javascript:void(0);" title="" data-toggle-tooltip="tooltip"
                            data-original-title="Clear all " class="btn btn-danger clearsearchtext px-4"
                            @click="Clearsearch">
                            <em class="fa fa-refresh"></em>{{ $t('Clear') }}
                        </a>
                    </div>
                </div>
            </div>
        </div>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="IsShowAction" :showCheckBox="true"
            ModuleName="PROJECT" SubModuleCode="Task" IdentityColumn="task_id" :HeaderText="$t('ProjectTasks')"
            :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :LegendArray="LegendArray" :SearchFields="false"
            :ListDataCallBackFunction="FetchTaskList" :SortExp="SortExp" :SortBy="SortBy"
            :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod" tableClasses="table-fix-header"
            v-on:ActionButtonClick="actionButtonClick" v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'status_id'">
                    <listing-status :isfor="'TASKLISTING'" ref="updatestatus" v-bind:dataid="data.row.task_id"
                        data-controller="Task" v-bind:statuslist="StatusList" v-bind:item="data"
                        v-bind:parentid="data.row.task_id" dataController="Task" dataAction="TaskStatusUpdate"
                        v-bind:dataselected="data.row.status_name" v-bind:callbackfunction="FetchTaskList"
                        v-bind:isselectedvaluestring="true">
                    </listing-status>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'priority_id'">
                    <div class="cstm-drop-btn" v-if="data.row.priority_name != null">
                        <select id="crmlistingStatus_span" v-model="data.row.priority_id" class="w-100"
                            :style="{ backgroundColor: data.row.color_code, color: '#ffffff' }"
                            @change="CommonPriortyUpdate(data.row, $event)">
                            <option v-for="(item, index) in PriorityData" :key="index" :value="item.value">{{ item.name
                            }}</option>
                        </select>
                    </div>
                    <span class="d-block" v-else>
                        {{ $t('NA') }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'task_name'">
                    <a class="task-dec" @click="ParentTask(data.row, 'Task')" :title="data.row.task_name"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        <span v-if="data.row.task_type === 'T' || data.row.task_type === 'SB'" class="text-primary fa fa-check-square mr-1"
                            title="Task"></span>
                        <span v-else-if="data.row.task_type === 'B'" class="text-danger fa fa-warning mr-1"
                            title="Bug"></span>
                        <span v-else-if="data.row.task_type === 'S'" class="text-success fa fa-film mr-1"
                            title="Story"></span>
                        {{ data.row.task_number }} {{ data.row.task_name }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'planned_start_date'">
                    <div :title="data.row.planned_start_date == null ? '--' : $d(data.row.planned_start_date)">

                        {{
                            data.row.planned_start_date == null ? '--' : $d(data.row.planned_start_date)
                        }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'sprint_name'">
                    <div :title="data.row.sprint_name == null ? '--' : data.row.sprint_name" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.sprint_name == null ? '--' : data.row.sprint_name }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'ComponentName'">
                    <div :title="data.row.ComponentName == null ? '--' : data.row.ComponentName" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.ComponentName == null ? '--' : data.row.ComponentName }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'EnvironmentName'">
                    <div :title="data.row.EnvironmentName == null ? '--' : data.row.EnvironmentName" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.EnvironmentName == null ? '--' : data.row.EnvironmentName }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'CreatedName'">
                    <div :title="data.row.ComponentName == null ? '--' : data.row.CreatedName" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.ComponentName == null ? '--' : data.row.CreatedName }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'ModifiedName'">
                    <div :title="data.row.ModifiedName == null ? '--' : data.row.ModifiedName" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.ModifiedName == null ? '--' : data.row.ModifiedName }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'planned_end_date'">
                    <div :title="data.row.planned_end_date == null ? '--' : $d(data.row.planned_end_date)">
                        {{ data.row.planned_end_date == null ? '--' : $d(data.row.planned_end_date) }}
                    </div>
                </template>
                   <template v-if="data.column.COLUMN_NAME == 'created_at'">
                    <div :title="data.row.created_at == null ? '--' : $d(data.row.created_at)">

                        {{
                            data.row.created_at == null ? '--' : $d(data.row.created_at)
                        }}
                    </div>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'modified_at'">
                    <div :title="data.row.modified_at == null ? '--' : $d(data.row.modified_at)">

                        {{
                            data.row.modified_at == null ? '--' : $d(data.row.modified_at)
                        }}
                    </div>
                </template>                 
                    <template v-if="data.column.COLUMN_NAME == 'Tag'">
                        <div class="user-count-wrapper" @mouseover="showTag(data.row)"  @mouseleave="hideTag(data.row)">
                            <a href="javascript:;" class="text-dark single-action" :class="{ 'disabled': !CheckDisabled() }">
                                <em class="fas fa-tag"></em>
                                <span v-if="data.row.TagNumber > 0" class="noti-circle noti-green">{{ data.row.TagNumber }}</span>
                            </a>
                            <div class="viewmoretagsbase_ptl showTags" v-if="data.row.istagover">
                                <div class="popover-arrowss_ptl"></div>
                                <div class="viewmoretags_ptl">
                                    <span class="head">{{$t('Tags')}}</span>
                                    <div class="outerbase">
                                        <span v-for="(item, index) in data.row.Tag" :key="index">{{
                                            index + 1 }}. {{ TruncateStr(item.TagName, 15) }}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </template>
                <template v-if="data.column.COLUMN_NAME == 'task_description'">
                    <span :title="stripHtmlTags(data.row.task_description)"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;    text-overflow: ellipsis;"
                        v-html="TruncateStr(data.row.task_description, 30)">
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'CompleteTask'">
                    <div class="Task" :title="data.row.Current_Progress + '%'">
                        <div :class="['c100', 'small', 'green', 'p' + parseInt(data.row.Current_Progress)]">
                            <span>{{ data.row.Current_Progress }}%</span>
                            <div class="slice">
                                <div class="bar"></div>
                                <div class="fill"></div>
                            </div>
                        </div>
                    </div>
                    <a href="javascript:;" @click="CheckDisabled() && UpdateProgress(data.row)"
                        v-if="data.row.status_name != 'Completed'" :title="data.row.Current_Progress"
                        :class="{ 'text-success': true, 'align-top': true, 'mt-3': true, 'd-inline-block': true, 'text-right': true, 'single-action': true, 'disabled': !CheckDisabled() }"
                        data-toggle-tooltip="tooltip" data-original-title="Manage Progress"><em
                            class="fa fa-pencil action-icon"></em></a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'Team'">
                    <div class="user-count-wrapper" @mouseover="showAssignUser(data.row) && CheckDisabled()"
                        @mouseleave="hideAssignUser(data.row) && CheckDisabled()">
                        <span v-if="data.row.Number == 0">
                            <a @click="OpenAssignedUser(data.row)"
                                :class="['text-dark', 'single-action', { 'disabled': !CheckDisabled() }]"
                                :href="CheckDisabled() ? 'javascript:;' : '#'">
                                <em class="fa fa-user-plus"></em>
                            </a>
                        </span>
                        <span v-else>
                            <a @click="OpenAssignedUser(data.row)"
                                :class="['text-dark', 'single-action', { 'disabled': !CheckDisabled() }]"
                                :href="CheckDisabled() ? 'javascript:;' : '#'">
                                <em class="fa fa-user"></em>
                                <span class="noti-circle noti-green">{{ data.row.Number }}</span>
                            </a>
                        </span>
                        <div class="viewmoretagsbase_ptl showTags" v-if="data.row.ispopover">
                            <div class="popover-arrowss_ptl"></div>
                            <div class="viewmoretags_ptl">
                                <span class="head" title="Prashant shukla QA">{{$t(TabsArray.find(t => t.displayCode
                                    === "PROJECT_TEAM")?.displayName || 'Team')}}</span>
                                <div class="outerbase">
                                    <span v-for="(item, index) in data.row.AssignUser" :key="index">{{
                                        index
                                        + 1 }}. {{ TruncateStr(item, 15) }}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </template>
            </template>
        </tg-list>
        <div class="add-backlog-btn border bg-light float-left w-100 p-3 mb-5" v-if="CheckDisabled()">
            <a v-if="!IsAddTask" class="w-100 text-dark" @click="AddTask" type="button"><em
                    class="fa fa-plus pr-2"></em>{{
                        $t('Create') }} {{ $t(NewTabName) }}</a>
            <div class="input-group w-100 " v-if="IsAddTask">

                <div class="mr-3">

                    <div class="d-inline">
                        <div class="checklist-icon bg-light position-relative">
                            <div v-if="IsTask" class="text-primary fa fa-check-square"></div>
                            <div v-if="IsBug" class="text-danger fa fa-warning"></div>
                            <div v-if="IsStory" class="text-success fa fa-film"></div>
                            <a class="dropdown pl-2">
                                <em class="fa fa-angle-down" id="dropdownMenu2" data-toggle="dropdown"
                                    aria-haspopup="true" aria-expanded="false" aria-hidden="true"></em>
                                <div class="dropdown-menu" aria-labelledby="dropdownMenu2">
                                    <button @click="TypeCheck('T')" class="dropdown-item" type="button"><em
                                            class="fa fa-check-square text-primary pr-2"></em>{{ $t('Task') }}</button>
                                    <button @click="TypeCheck('B')" class="dropdown-item" type="button"><em
                                            class="fa fa-warning text-danger pr-2"></em>{{ $t('Issue') }}</button>
                                    <button @click="TypeCheck('S')" class="dropdown-item" type="button"><em
                                            class="fa fa-film text-success pr-2"></em>{{ $t('Story') }}</button>
                                </div>
                            </a>
                        </div>
                    </div>
                </div>
                <input type="text" @keydown.enter="SaveTask" v-model="txtTaskTitle" class="form-control px-1 bg-white"
                    :placeholder="`${$t('Enter')} ${$t(NewTabName)} ${$t('Name')}`" aria-label=""
                    aria-describedby="basic-addon1">
                <div class="col-sm-1 pt-1 mt-1">
                    <a class="actions-onclick" title="Save" @click="SaveTask"><em
                            class="fa fa-save action-icon text-success"></em></a>
                    <a @click="IsHideAddTask" title="Close" class="actions-onclick"><em
                            class="fa fa-close action-icon text-danger"></em></a>
                </div>
            </div>
            <div class="mr-5 w-100">
                <small class="text-danger" v-if="errorMessage && IsAddTask">{{ errorMessage }}</small>
            </div>
        </div>
        <AddImportTask v-if="ProjectTasklistingSchema" :ProjectName="ProjectName" :Type="'Task'"></AddImportTask>
        <EditTask v-if="IsEditTask" :MainProjectData="ProjectDetailData" :projectdata.sync="projectdata"
            :projectCurrency="projectCurrency" @callbackfunction="UpdateTask" :isHideSprint="isHideSprint"
            :NewTabName="NewTabName" :TabsArray="TabsArray" :modeType="modeType" :IssueType="false" :ProjectOwner="ProjectOwner" :checkPmUser="checkPmUser">
        </EditTask>
        <modaltaskprogress v-if="IsUpdateProgress" :TaskItemData="TaskItemData" :Type="IsTaskType"
            @GetTaskList="GetTaskList" @CloseModal="CloseModal"> </modaltaskprogress>
        <TaskBulkAction v-if="IsBulkAction" @CloseBulkAction="CloseBulkAction" :BulkActionTaskIds="BulkActionTaskIds"
            :MainProjectData="ProjectDetailData" @RefreshTaskList="FetchTaskList" Type="Task"></TaskBulkAction>
        <AssignedUserModal v-if="IsAssignedUser" :BacklogId="ParentTaskId" :AssigenedUser="taskData"
            @CallbackFunction="FetchTaskList" :NewTabName="NewTabName" :AssignTabTabName="NewTabName"  :TabsArray="TabsArray"
            :AssignSprintTab="NewTabName" :ProjectOwner="ProjectOwner" :checkPmUser="checkPmUser"></AssignedUserModal>
    </section>
</template>
<script>
import DataService from '../../../../services/DataService.js';
import schema from '../../Project/ProjectDetailLeftAllTabs/ProjectTasklistingSchema.js';
import AddImportTask from './AddImportTask.vue';
import EditTask from '../../../../components/Modal/EditTask.vue'
import modaltaskprogress from '../../../../components/Modal/modaltaskprogress.vue';
import TaskBulkAction from '../../../../components/Modal/TaskBulkAction.vue';
import AssignedUserModal from '../../../../components/Modal/AssignedUserModal.vue';
import moment from 'moment';
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
    components: { AddImportTask, EditTask, modaltaskprogress, TaskBulkAction, Treeselect, AssignedUserModal },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        isHideSprint: {
            type: Boolean,
            required: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        projectCurrency: {
            type: String
        },
        ProjectOwner: {
            type: Boolean
        },
        projectName:{
            type: String,
            required: true
        },
        projectHours:{
            type: Number,
            required: true
        },
    },
    data() {
        return {
            Key: 0,
            dataTruncateLength: 20,
            isTaskSave: false,
            projectdata: null,
            ProjectDetailData: null,
            IsEditTask: false,
            IsType: 'Task',
            IsTaskType: 'Project',
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            IsPriority: null,
            CompanyId: null,
            PageSize: 10,
            PageNumber: 1,
            errorMessage: '',
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            StatusList: [],
            SortBy: '',
            SortExp: '',
            taskId: '',
            Headers: [],
            ListingData: [],
            searchCondition: '',
            Buttons: schema.buttons,
            IsAddTask: false,
            txtTaskTitle: '',
            isSavingTask: false,
            ProjectId: 0,
            ProjectName: '',
            completionPercentage: 0,
            listActions: schema.listActions,
            IsAssignedUser: false,
            ParentTaskId: 0,
            modeType: null,
            ProjectTasklistingSchema: false,
            IsShowAction: true,
            IsUpdateProgress: false,
            TaskItemData: null,
            taskData: '',
            UserType: '',
            LegendArray: [{
                class: 'text-primary fa fa-check-square mr-1',
                text: (this.$t('Task'))
            },
            {
                class: 'text-danger fa fa-warning ml-2 mr-1',
                text: (this.$t('Issue'))
            },
            {
                class: 'text-success fa fa-film text-success ml-2 mr-1',
                text: (this.$t('Story'))
            }
            ],
            IsTask: true,
            IsStory: false,
            IsBug: false,
            IssueTypeId: 'T',
            IsBulkAction: false,
            PriorityData: [],
            BulkActionTaskIds: '',
            StatusData: [],
            TypeFilter: null,
            QuickFilter: null,
            StatusFilter: null,
            PriorityFilter: null,
            ProjectBacklogType: [],
            QuickfilterBacklogType: [{ label: 'Un Assign', id: 'UnAssign' }],
            IsTaskName: '',
            FilterPriorityData: [],
            SprintData: [],
            SprintFilter: null
        }
    },
    watch: {
        NewTabName: {
            handler(newTabName) {
                if (newTabName) {
                    this.updateHeaders(newTabName);
                }
            },
            immediate: true
        },
        txtTaskTitle(val) {
            if (val.length > 200) {
                this.errorMessage = "The Task Name field may not be greater than 200 characters";
            }
            else {
                this.errorMessage = '';
            }
        }
    },
    created: async function () {
        var ths = this;
        ths.ProjectId = ths.projectId;
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.userId = ths.GetUserInfo.ID;
        ths.UserType = ths.GetUserInfo.UserType;
        if (!ths.Headers || ths.Headers.length === 0) {
            ths.Headers = JSON.parse(JSON.stringify(schema.TableHeader));
        }
        if (ths.NewTabName) {
            ths.updateHeaders(ths.NewTabName);
        }
        ths.StatusDropdown();
        ths.GetProjectPriority();
        ths.GetProjectBacklogType();
        ths.FetchMemberListing();
        await this.GetProjectSprint();
        await ths.GetProjectDetails();
        await ths.FetchTaskList();
    },
    computed: {
        dynamicPlaceholderr() {
            return `${this.$t(this.NewTabName)} Name...`;
        }
    },
    methods: {
        getFilterLimitText(count) {
            return `+${count}`;
        },
        async GetProjectSprint() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_SPRINT&search=&refId=${vm.ProjectId}`;
            await DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach((item) => {
                                var obj = {
                                    id: item.value,
                                    label: item.name
                                }
                                vm.SprintData.push(obj);
                            })
                        }
                    }
                }
            })
        },
        FetchMemberListing: async function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    id: element.value,
                                    label: element.name
                                }
                                ths.QuickfilterBacklogType.push(obj);
                            })
                        }
                        else {
                            ths.QuickfilterBacklogType = [];
                        }
                    }
                }
            });
        },
        GetProjectBacklogType() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_BACKLOG&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach((item) => {
                                var obj = {
                                    id: item.value,
                                    label: item.name
                                }
                                vm.ProjectBacklogType.push(obj);
                            })
                        }
                    }
                }
            })
        },
        CommonPriortyUpdate(data, evt) {
            var vm = this;
            var postJSON = {
                ID: data.task_id,
                StatusId: evt.target.value,
                IsFor: 'UPDATE_PROJECT_PRIORTY'
            };
