        getPercentage(estimatedHours, spentHours) {
            if (
                !estimatedHours ||
                isNaN(estimatedHours) ||
                estimatedHours <= 0 ||
                !spentHours ||
                isNaN(spentHours) ||
                spentHours <= 0
            ) {
                return 0;
