<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered mw-800">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('Bulk') }} {{ $t('Action') }}</h4>
                        <button type="button" class="close" v-on:click="CloseBulkAction">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <div class="col-md-12 col-lg-12 unides_formcontrol p-0">
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2" v-if="hasAccess">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('TaskProperties') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableStatus"
                                        name="checkbox" v-model="enableStatus">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableStatus"></label>
                                </div>
                                <label>{{ $t('Status') }}</label>
                                <Field name="Status">
                                    <select class="form-control" id="DueDate" v-model="StatusId" name="Status"
                                        :disabled="!enableStatus">
                                        <option value="0">Select Status</option>
                                        <option v-for="(item, index) in StatusList" :key="index"
                                            :value="item.STATUS_ID">{{ item.STATUS }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enablePriority"
                                        name="checkbox" v-model="enablePriority">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enablePriority"></label>
                                </div>
                                <label>{{ $t('Priority') }}</label>
                                <Field name="Priority">
                                    <select class="form-control" id="Priority" v-model="PriorityId" name="Priority"
                                        :disabled="!enablePriority">
                                        <option value="0">Select Priority</option>
                                        <option v-for="(item, index) in PriorityData" :key="index" :value="item.value">
                                            {{ item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableProgress"
                                        name="checkbox" v-model="enableProgress">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableProgress"></label>
                                </div>
                                <label>{{ $t('Progress(%)') }}</label>
                                <Field :rules="{ 'required': false }" name="Progress">
                                    <input v-model="Progress" name="Progress" type="text" placeholder="Enter Progress"
                                        v-bind:class="{ 'form-control': true }" :disabled="!enableProgress" />
                                </Field>
                            </div>
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2 mt-3" v-if="hasAccess">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('Sprint') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableSprint"
                                        name="checkbox" v-model="enableSprint">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableSprint"></label>
                                </div>
                                <label>{{ $t('Sprint') }}</label>
                                <Field name="enableSprint">
                                    <select class="form-control" id="enableSprint" name="enableSprint" v-model="Sprint"
                                        :disabled="!enableSprint">
                                        <option value="0">Select Sprint</option>
                                        <option v-for="(item, index) in SprintData" :key="index"
                                            :value="item.value">{{
                                                item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2 mt-3">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('Assignment') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                            <div class="form-group">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableAssign"
                                        name="checkbox" v-model="enableAssign">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableAssign"></label>
                                </div>
                                <label>{{ $t('Assign/Unassign') }}</label>
                                <Field name="Assign/Unassign">
                                    <select class="form-control" id="Assign/Unassign" name="Assign/Unassign" v-model="UserAssign"
                                        :disabled="!enableAssign">
                                        <option value="0">Select Assign / Unassign</option>
                                        <option v-for="(item, index) in TeamMemberData" :key="index"
                                            :value="item.value">{{
                                                item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableTeam"
                                        name="checkbox" v-model="enableTeam">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableTeam"></label>
                                </div>
                                <label>{{ $t('Team') }}</label>
                                <Field name="Team">
                                    <select class="form-control" id="Team" name="Team" :disabled="!enableTeam" v-model="TeamAssign">
                                        <option value="0">Select Team</option>
                                        <option v-for="(item, index) in ProjectTeamData" :key="index"
                                            :value="item.value">{{
                                                item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2 mt-3" v-if="hasAccess">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('Planning') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                             <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableStartDate"
                                        name="checkbox" v-model="enableStartDate">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableStartDate"></label>
                                </div>
                                <label>Start Date</label>
                                <Field name="DueDate">                                    
                                    <v-date-picker v-model="PlanningStartDate" class="input-group" :disabled="!enableStartDate">
                                            <template v-slot="{ inputValue, togglePopover }">
                                            <input :disabled="!enableStartDate"
                                                placeholder="MM/DD/YYYY"
                                                :value="inputValue"
                                                class="form-control"                                                
                                            />
                                            <div
                                                class="input-group-append"
                                                @click="togglePopover()"
                                                style="cursor: pointer"
                                            >
                                                <span class="input-group-text">
                                                <em class="fa fa-calendar"></em>
                                                </span>
                                            </div>
                                            </template>
                                        </v-date-picker>
                                </Field>
                            </div>
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableDueDate"
                                        name="checkbox" v-model="enableDueDate">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableDueDate"></label>
                                </div>
                                <label>Due Date</label>
                                <Field name="DueDate">
                                   
                                    <v-date-picker v-model="PlanningDueDate" class="input-group" :disabled="!enableDueDate">
                                            <template v-slot="{ inputValue, togglePopover }">
                                            <input
                                                placeholder="MM/DD/YYYY"
                                                :value="inputValue"
                                                class="form-control"  :disabled="!enableDueDate"                                               
                                            />
                                            <div
                                                class="input-group-append"
                                                @click="togglePopover()"
                                                style="cursor: pointer"
                                            >
                                                <span class="input-group-text">
                                                <em class="fa fa-calendar"></em>
                                                </span>
                                            </div>
                                            </template>
                                        </v-date-picker>
                                </Field>
                            </div>                           
                            <div class="form-group" v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableEstimate"
                                        name="checkbox" v-model="enableEstimate">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableEstimate"></label>
                                </div>
                                <label>Estimate (hrs)</label>
                                <Field :rules="{ 'required': false }" name="Estimate">
                                    <input v-model="EstimateHours" name="Estimate" type="text"
                                        placeholder="Enter Estimate Hours" v-bind:class="{ 'form-control': true }"
                                        :disabled="!enableEstimate" />
                                </Field>
                            </div>
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2  mt-3" v-if="Type =='Task' && hasAccess">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('Workflow') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                            <div class="form-group" v-if="Type=='Task' && hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableStage"
                                        name="checkbox" v-model="enableStage">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableStage"></label>
                                </div>
                                <label>{{ $t('Stage') }}</label>
                                <Field name="stage">
                                    <select class="form-control" id="stage" name="stage" :disabled="!enableStage" v-model="StageIds" @change="StageChange($event)">
                                        <option value="0">Select Stage</option>
                                        <option v-for="(item, index) in StageData" :key="index" :value="item.value">{{
                                            item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group" v-if="Type=='Task' && hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enablePhase"
                                        name="checkbox" v-model="enablePhase">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enablePhase"></label>
                                </div>
                                <label>{{ $t('Phase') }}</label>
                                <Field name="phase">
                                    <select class="form-control" id="phase" name="phase" :disabled="!enablePhase" v-model="PhaseIds">
                                        <option value="0">Select Phase</option>
                                        <option v-for="(item, index) in PhaseData" :key="index" :value="item.value">{{
                                            item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group"  v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableTags"
                                        name="checkbox" v-model="enableTags">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableTags"></label>
                                </div>
                                <label>Tags</label>
                                <Field :rules="{ 'required': false }" name="Tags">
                                    <select class="form-control" id="phase" name="phase" :disabled="!enableTags" v-model="TagIds">
                                        <option value="0">Select Tags</option>
                                        <option v-for="(item, index) in TagData" :key="index" :value="item.value">{{
                                            item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group"  v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableComponent"
                                        name="checkbox" v-model="enableComponent">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableComponent"></label>
                                </div>
                                <label>{{ $t('Component') }}</label>
                                <Field :rules="{ 'required': false }" name="Tags">
                                    <select class="form-control" id="phase" name="phase" :disabled="!enableComponent" v-model="ComponentId">
                                        <option value="0">Select Component</option>
                                        <option v-for="(item, index) in ComponentData" :key="index" :value="item.value">{{
                                            item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="form-group"  v-if="hasAccess">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableEnvirements"
                                        name="checkbox" v-model="enableEnvirements">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableEnvirements"></label>
                                </div>
                                <label>{{ $t('Evirement') }}</label>
                                <Field :rules="{ 'required': false }" name="Tags">
                                    <select class="form-control" id="phase" name="phase" :disabled="!enableEnvirements" v-model="EnvirementId">
                                        <option value="0">Select Evirement</option>
                                        <option v-for="(item, index) in EnvirementData" :key="index" :value="item.value">{{
                                            item.name }}</option>
                                    </select>
                                </Field>
                            </div>
                            <div class="col-lg-12 mb-0 float-left p-0 mb-2  mt-3">
                                <div class="heading-border">
                                    <h5 class="h5"><span>{{ $t('Description') }}</span></h5>
                                </div>
                            </div>
                            <div class="clearfix"></div>
                            <div class="form-group">
                                <div class="custom-control custom-checkbox">
                                    <input class="chkItems custom-control-input" type="checkbox" id="enableComment"
                                        name="checkbox" v-model="enableComment">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                        for="enableComment"></label>
                                </div>
                                <label>{{$t('AddText')}}</label>
                                <Field :rules="{ 'required': false }" name="comment">
                                    <textarea class="form-control" id="comment" name="comment" v-model="CommentText"
                                        :disabled="!enableComment"></textarea>
                                </Field>
                            </div></div>
                            <div class="text-end text-right col-12 p-0 mt-3">
                                <button type="submit" class="btn btn-success" @click="SaveBulkAction"><i
                                        class="fa fa-save pr-2"></i>{{ $t('Save')
                                    }}</button>
                                <button type="button" class="btn btn-danger" style="margin-left: 5px;"
                                    @click="CloseBulkAction"><i class="fa fa-close pr-2"></i>{{ $t('Cancel') }}</button>
                            </div>
                        
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
export default {
    props:{
        BulkActionTaskIds:{
            type:String,
            required:true
        },
        Type:{
            type:String,
            required:true 
        },
        MainProjectData: {
            type: Object,
            required: false
        },
        ProjectOwner: {
            type: String
        }, checkPmUser: {
            type: Boolean,
            required: true
        },
    },
    data() {
        return {
            isLoading: false,
            PriorityId: 0,
            ProjectId: 0,
            StatusId: 0,
            PlanningDueDate: null,
            PlanningStartDate: null,
            PriorityData: [],
            StatusList: [],
            changed:'',
            TeamMemberData: [{ name: 'Un Assign', value: 'UnAssign' },],
            SprintData:[],
            ProjectTeamData: [],
            PhaseData: [],
            StageData: [],
            TagData: [],
            ComponentData:[],
            EnvirementData:[],
            Tags: '',
            EstimateHours: '',
            Progress: '',
            UserAssign:0,
            Sprint:0,
            TeamAssign:0,
            StageIds:0,
            PhaseIds:0,
            TagIds:0,
            ComponentId:0,
            EnvirementId:0,
            CommentText:'',
            enableStatus: false,
            enablePriority: false,
            enableProgress: false,
            enableAssign: false,
            enableSprint:false,
            enableTeam: false,
            enableDueDate: false,
            enableStartDate: false,
            enableEstimate: false,
            enableStage: false,
            enablePhase: false,
            enableTags: false,
            enableComponent:false,
            enableEnvirements:false,
            enableComment: false,
            hasAccess:false,
        }
    },
    created: function () {        
        var ths = this;
        ths.MainProjectData;
        ths.ProjectId = parseInt(ths.$route.params.projectId);
        ths.StatusDropdown();
        ths.GetProjectPriority();
        ths.GetUsers();
        ths.GetProjectTeam();
        ths.BindPhaseDropdown();
        ths.BindStageDropdown();
        ths.BindTagDropdown(); 
        ths.GetSprint();    
        ths.BindComponentDropdown();
        ths.BindEnvirementDropdown();
        ths.CheckDisabled();   
    },
    computed: {        
    minDate() {
        if(this.MainProjectData){
        return this.MainProjectData.PLANNED_START_DATE
        ? new Date(this.MainProjectData.PLANNED_START_DATE)
        : null;
        }
    },
    maxDate() {
       if(this.MainProjectData){
        return this.MainProjectData.PLANNED_END_DATE
        ? new Date(this.MainProjectData.PLANNED_END_DATE)
        : null;
       }
    }
    },
    methods: {
        CheckDisabled() {
            
            const isClientOrNU = this.GetUserInfo.UserType === 'CL' || this.GetUserInfo.UserType === 'NU';
            const isAdminOrPM = this.GetUserInfo.UserType === 'CA' || this.GetUserInfo.UserType === 'PM';
            const hasPmAccess = this.checkPmUser || this.ProjectOwnerId;
            return  this.hasAccess=(isClientOrNU && hasPmAccess) || isAdminOrPM;
        },
        FetchAddEditStage: function () {
            var ths = this;
            var url = `projectId=${ths.ProjectId}`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.result.DATA.length > 0) {
                    ths.AddEditStageListing = response.data.result.DATA;                    
                } 
            })
        },
        BindPhaseDropdown: function () {
            var ths = this;
            var url = `id=&moduleName=&type=PHASE_NAME&search=&refId=0`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.DATA.length > 0) {
                    ths.PhaseData = response.data.DATA;
                }
            })
        },
        BindTagDropdown: function () {
            var ths = this;
            var url = `id=&moduleName=PROJECT&type=HR_TAG&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.DATA.length > 0) {
                    ths.TagData = response.data.DATA;
                }
            })
        },
        BindStageDropdown: function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=&type=PROOJECT_STAGE_NAME&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.DATA.length > 0) {
                    ths.StageData = response.data.DATA;
                }
            })
        },
        BindComponentDropdown: function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=&type=PROJECT_COMPONENT_NAME&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.DATA.length > 0) {
                    ths.ComponentData = response.data.DATA;
                }
            })
        },
        BindEnvirementDropdown: function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=&type=PROJECT_ENVIRONMENT_NAME&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.data.DATA.length > 0) {
                    ths.EnvirementData = response.data.DATA;
                }
            })
        },
        GetProjectTeam() {
            var vm = this;
            var url = `id=${vm.ProjectId}&moduleName=&type=PROJECT_TEAM_ASSOCIATE&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            vm.ProjectTeamData = response.data.DATA;
                        }
                    }
                }
            })
        },
        StatusDropdown: function () {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response) => {
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data;
                }
            });
        },
        GetProjectPriority() {
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            this.PriorityData = response.data.DATA;
                        }
                    }
                }
            })
        },
        GetUsers() {
            var vm = this;
            var url = `id=${vm.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.status === 200 && response.data?.DATA?.length > 0) {
                            vm.TeamMemberData = response.data.DATA.map(element => ({
                                name: element.name,
                                value: element.value
                            }));
                            vm.TeamMemberData = [
                            { name: 'Un Assign', value: 0 },
                            ... vm.TeamMemberData
                        ];
                        }
                    }
                }
            });
        },
        GetSprint() {
            var vm = this;
            var url = `id=&moduleName=PROJECT&type=PROJECT_SPRINT&search=&refId=${vm.ProjectId}`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            vm.SprintData=response.data.DATA;
                        }
                    }
                }
            })
        },
        StageChange(evt){            
            var ths = this;
            ths.StageIds = evt.target.value;
            var filteredStageList = this.AddEditStageListing.filter(item => {
                return item.STAGE_ID == Number(this.StageIds);
            });
            if(filteredStageList.length > 0){
                this.PhaseIds=filteredStageList[0].PHASE_ID;
            }

        },
        CloseBulkAction() {
            this.$emit('CloseBulkAction');
        },
        SaveBulkAction() { 
            var ths =this;   
            ths.isLoading=true;      
            const bulkUpdateData = {
                taskIds: ths.BulkActionTaskIds,
                ProjectId:ths.ProjectId,
                statusId:0,
                priorityId:0,
                progress:0,
                UserAssign:0,
                TeamAssign:0,
                dueDate:null,
                startDate:null,
                estimateHours:0,
                StageId:0,
                PhaseIds:0,
                TagIds:0,
                CommentText:'',
                SprintId:0,
                ComponentId:0,
                EnvironmentId:0
            };
            if (this.enableStatus && this.StatusId > 0) {
                bulkUpdateData.statusId = this.StatusId;
            }
            if (this.enablePriority && this.PriorityId > 0) {
                bulkUpdateData.priorityId = this.PriorityId;
            }
            if (this.enableProgress && this.Progress) {
                bulkUpdateData.progress = this.Progress;
            }
            if (this.enableAssign) {
                bulkUpdateData.UserAssign=this.UserAssign;
            }
            if (this.enableSprint) {
                bulkUpdateData.SprintId=this.Sprint;
            }
            if (this.enableTeam) {
                bulkUpdateData.TeamAssign=this.TeamAssign;
            }
            if (this.enableDueDate && this.PlanningDueDate) {
                bulkUpdateData.dueDate = this.PlanningDueDate;
            }
            if (this.enableStartDate && this.PlanningStartDate) {
                bulkUpdateData.startDate = this.PlanningStartDate;
            }
            if (this.enableEstimate && this.EstimateHours) {
                bulkUpdateData.estimateHours = this.EstimateHours;
            }
            if (this.enableStage) {
                bulkUpdateData.StageId=this.StageIds;
            }
            if (this.enablePhase) {
                bulkUpdateData.PhaseIds=this.PhaseIds;
            }
            if (this.enableTags) {
               bulkUpdateData.TagIds=this.TagIds;
            }
            if (this.enableComponent) {
               bulkUpdateData.ComponentId=this.ComponentId;
            }
            if (this.enableEnvirements) {
               bulkUpdateData.EnvironmentId=this.EnvirementId;
            }
            if (this.enableComment) { 
                bulkUpdateData.CommentText = this.CommentText;                
            } 
                      
            var objectPostString = JSON.stringify(bulkUpdateData);  
            DataService.SaveTaskBulkAction(objectPostString).then(function (response) {
                ths.isLoading=false;  
                if(response.data.result.DATA.length>0){
                    if (response.data.result.DATA[0].VALUE) {                        
                        ths.ShowAlert(ths.$t('UpdatedSuccess',[ths.$t('BulkAction')]), "success", true,  ths.$t("Alert"));
                        ths.CloseBulkAction();
                        ths.$emit('RefreshTaskList');
                    }
                    else {
                        ths.ShowAlert(ths.$t('UnknownErrorOccur'), "failure", true, ths.$t("Alert"));
                    }
                }
                
            }); 
        }
    }
}
</script>
